/*
 * HRI delivery-robot trust study — PsiTurk front end.
 *
 * Globals from exp.html (filled in by PsiTurk): uniqueId, adServerLoc, mode,
 * condition (0 = reliable, 1 = unreliable), counterbalance (0 = low autonomy first, 1 = mid first).
 * CLIP_SPEC comes from static/js/clip_spec.js (generated by hri_delivery.clips).
 *
 * Procedure (STUDY_DESIGN.md §8): consent (PsiTurk consent page) -> demographics -> NARS -> sound check ->
 * training video -> practice trial -> block 1 (3 trials + MDMT/reliance/manipulation checks) ->
 * block 2 (other autonomy level, other robot) -> open-ended question -> debrief.
 *
 * Data (Dr. Roy's checklist): experimental records (trials, practice, video/page events) go to trialdata via
 * record(); all pre- and post-experiment questions go to questiondata via saveQuestions(), one key per answer.
 * Every page shows a countdown in the header (soft limit: pages that ran over are listed in questiondata
 * 'pages_over_time').
 */
/* global PsiTurk, uniqueId, adServerLoc, mode, condition, counterbalance, CLIP_SPEC,
   NARS_ITEMS, NARS_SCALE, MDMT_ITEMS */

var psiTurk = new PsiTurk(uniqueId, adServerLoc, mode);
var params = new URLSearchParams(window.location.search);
// Test hooks, only honoured in debug mode: ?fast=1 plays videos at 16x; ?start=block1 skips straight to
// block 1 (to preview trial clips; nothing before it is recorded).
var FAST = (mode === 'debug' && params.get('fast') === '1');
var START = mode === 'debug' ? params.get('start') : null;   // 'block1' or 'block2'

var COND = parseInt(condition, 10) || 0;
var COUNTER = parseInt(counterbalance, 10) || 0;
var GROUP = COND === 0 ? 'reliable' : 'unreliable';
var ORDER = COUNTER === 0 ? ['low', 'mid'] : ['mid', 'low'];
var PATTERN = CLIP_SPEC.patterns[GROUP];
var VIDEO_DIR = 'static/videos/';
var attention = {};

psiTurk.recordUnstructuredData('group', GROUP);
psiTurk.recordUnstructuredData('autonomy_order', ORDER.join('-'));

// ------------------------------------------------------------------ helpers
var $c = function () { return document.getElementById('container-exp'); };

function show(html) {
  $c().innerHTML = html;
  window.scrollTo(0, 0);
}

// Progress in the header bar: step label + bar (0-1).
var STEPS = ['About you', 'Attitudes', 'Sound check', 'Training', 'Practice', 'Robot 1', 'Robot 2', 'Finish'];
function setStep(k, within) {
  var bar = document.getElementById('progress-bar'), lab = document.getElementById('step-label');
  if (bar) bar.style.width = Math.round(100 * (k + (within || 0)) / STEPS.length) + '%';
  if (lab) lab.textContent = 'Step ' + (k + 1) + ' of ' + STEPS.length + ' · ' + STEPS[k];
}

function clicked(selector) {
  return new Promise(function (resolve) {
    var els = document.querySelectorAll(selector);
    els.forEach(function (el) {
      el.addEventListener('click', function handler(ev) {
        els.forEach(function (e) { e.disabled = true; });
        resolve(ev.currentTarget);
      }, {once: true});
    });
  });
}

function record(obj) {
  obj.group = GROUP;
  obj.condition = COND;
  obj.counterbalance = COUNTER;
  obj.autonomy_order = ORDER.join('-');
  psiTurk.recordTrialData(obj);
}

function save() { psiTurk.saveData(); }

// Questionnaire answers -> questiondata, one key per answer (prefix e.g. 'b1_').
function saveQuestions(data, prefix) {
  Object.keys(data).forEach(function (k) { psiTurk.recordUnstructuredData((prefix || '') + k, data[k]); });
}

// ------------------------------------------------------------------ countdown timer (header)
var overTime = [];
var timerId = null;
function timerEl() {
  var el = document.getElementById('timer');
  var head = document.querySelector('.app-head .inner');
  if (!el && head) {
    el = document.createElement('span');
    el.id = 'timer';
    el.className = 'timer';
    head.appendChild(el);
  }
  return el;
}
function mmss(sec) { return Math.floor(sec / 60) + ':' + ('0' + sec % 60).slice(-2); }
function stopCountdown() { if (timerId) clearInterval(timerId); timerId = null; }
// Counts down `seconds` for this page. At 0 the timer turns red and asks for an answer; the page stays open.
function countdown(seconds, page) {
  stopCountdown();
  var el = timerEl();
  if (!el) return;
  var end = Date.now() + seconds * 1000;
  function tick() {
    var left = Math.max(0, Math.ceil((end - Date.now()) / 1000));
    el.className = 'timer' + (left <= 10 ? ' low' : '');
    el.textContent = 'Time left ' + mmss(left);
    if (left === 0) {
      el.className = 'timer up';
      el.textContent = 'Time is up: please answer';
      if (page && overTime.indexOf(page) < 0) overTime.push(page);
      stopCountdown();
    }
  }
  tick();
  timerId = setInterval(tick, 250);
}
// While a video plays the timer shows how much of the video is left.
function videoCountdown(v) {
  stopCountdown();
  var el = timerEl();
  if (el && v.duration) {
    el.className = 'timer video';
    el.textContent = 'Video ' + mmss(Math.max(0, Math.ceil((v.duration - v.currentTime) / (v.playbackRate || 1))));
  }
}

function robotBadge(robot) {
  return '<span class="robot-badge" style="--rc:' + robot.colour + '"><span class="dot"></span>' +
         robot.name + '</span>';
}

// ------------------------------------------------------------------ video player UI
// Title bar (robot + delivery target) above the video; under it a navy bar with the robot icon, a chat
// bubble showing what the robot says (timed by CLIP_CUES from videos/cues.js) and room for buttons.
var ROBOT_ICON = '<svg viewBox="0 0 48 48" width="44" height="44" aria-hidden="true">' +
  '<line x1="24" y1="4" x2="24" y2="11" stroke="#fff" stroke-width="3" stroke-linecap="round"/>' +
  '<circle cx="24" cy="4" r="3" fill="#fff"/>' +
  '<rect x="7" y="11" width="34" height="25" rx="8" fill="#fff"/>' +
  '<circle cx="17" cy="23" r="4" fill="#14213d"/><circle cx="31" cy="23" r="4" fill="#14213d"/>' +
  '<rect x="16" y="30" width="16" height="2.5" rx="1.2" fill="#14213d"/>' +
  '<rect x="2" y="18" width="4" height="10" rx="2" fill="#fff"/><rect x="42" y="18" width="4" height="10" rx="2" fill="#fff"/>' +
  '<rect x="13" y="38" width="22" height="7" rx="3" fill="#fff"/></svg>';

function playerHTML(robot, title, right) {
  return '<div class="player">' +
    '<div class="player-title"><span class="dot" style="background:' + robot.colour + '"></span>' +
    '<span class="ptitle">' + title + '</span><span class="pright">' + (right || '') + '</span>' +
    '<span class="snd">' + SOUND_ICON + 'Sound on</span></div>' +
    '<div id="stage"></div>' +
    '<div class="robot-bar"><div class="robot-icon">' + ROBOT_ICON + '<div class="robot-name">' + robot.name + '</div></div>' +
    '<div class="bubble empty" id="bubble"></div><div class="bar-buttons" id="bar-buttons"></div></div>' +
    '</div>';
}

function setBubble(text) {
  var b = document.getElementById('bubble');
  if (!b) return;
  if (text && b.textContent !== text) {
    b.classList.remove('pop'); void b.offsetWidth; b.classList.add('pop');
  }
  b.textContent = text || '';
  b.classList.toggle('empty', !text);
}

var SOUND_ICON = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" ' +
  'stroke-linejoin="round" aria-hidden="true"><path d="M11 5 6 9H2v6h4l5 4V5z" fill="currentColor"/>' +
  '<path d="M15.5 8.5a5 5 0 0 1 0 7M19 5a10 10 0 0 1 0 14"/></svg>';

// Plays a clip to the end (no controls, no seeking). Resolves with watch time in ms.
// The robot's messages appear in the chat bubble at the times recorded with the clip.
function playClip(name, caption) {
  return new Promise(function (resolve) {
    var stage = document.getElementById('stage');
    stage.innerHTML = '<div class="screen"><video id="clip" playsinline' + (FAST ? ' muted' : '') + ' preload="auto" src="' + VIDEO_DIR + name +
      '"></video><div class="subtitle" id="subtitle"></div></div><div class="vprog"><div id="vprog"></div></div>' +
      '<p class="hint" id="clip-status">' + (caption ? caption + ' ' : '') + 'The video is playing…</p>';
    var v = document.getElementById('clip');
    var cues = (typeof CLIP_CUES !== 'undefined' && CLIP_CUES[name]) ? CLIP_CUES[name].cues : [];
    var voice = (typeof CLIP_CUES !== 'undefined' && CLIP_CUES[name] && CLIP_CUES[name].voice) || [];
    var bar = document.querySelector('.robot-bar');
    var shown = -1;
    function updateCues() {
      var tt = v.currentTime;
      videoCountdown(v);
      if (bar) bar.classList.toggle('speaking', !v.ended && voice.some(function (s) { return tt >= s.t && tt < s.t + s.dur; }));
      if (v.duration) document.getElementById('vprog').style.width = (100 * tt / v.duration) + '%';
      var k = -1;
      for (var i = 0; i < cues.length; i++) if (cues[i].t <= v.currentTime + 0.02) k = i;
      if (k === shown || k < 0) return;
      shown = k;
      setBubble(cues[k].message);
      var sub = document.getElementById('subtitle');
      sub.textContent = cues[k].caption || '';
      sub.classList.toggle('on', !!cues[k].caption);
    }
    setBubble('');
    var t0 = performance.now();
    if (FAST) v.playbackRate = 16;
    v.addEventListener('ended', function () {
      v.currentTime = v.duration;
      updateCues();
      if (bar) bar.classList.remove('speaking');
      document.getElementById('clip-status').textContent = '';
      resolve(Math.round(performance.now() - t0));
    }, {once: true});
    v.addEventListener('error', function () {
      document.getElementById('clip-status').innerHTML =
        '<b>Video failed to load (' + name + ').</b> Please contact the researcher.';
      record({phase: 'error', clip: name, error: 'video_load_failed'});
    });
    // Block seeking via keyboard / context menu.
    v.addEventListener('seeking', function () { if (!v.ended && v.currentTime > 0.1) v.currentTime = v._last || 0; });
    v.addEventListener('timeupdate', function () { if (!v.seeking) v._last = v.currentTime; updateCues(); });
    var p = v.play();
    if (p && p.catch) {
      p.catch(function () {
        document.getElementById('clip-status').innerHTML =
          '<button class="btn" id="play-btn">▶ Play video (with sound)</button>';
        document.getElementById('play-btn').onclick = function () { v.play(); this.remove(); };
      });
    }
  });
}

// Radio-button matrix. items: [{id, text}], scale: [{value, label}]
function matrix(items, scale, cls) {
  var h = '<table class="matrix ' + (cls || '') + '"><thead><tr><th></th>';
  scale.forEach(function (s) { h += '<th>' + s.label + '</th>'; });
  h += '</tr></thead><tbody>';
  items.forEach(function (it) {
    h += '<tr data-item="' + it.id + '"><td class="item">' + it.text + '</td>';
    scale.forEach(function (s) {
      h += '<td><label><input type="radio" name="' + it.id + '" value="' + s.value + '"' +
           ' aria-label="' + s.label + '"></label></td>';
    });
    h += '</tr>';
  });
  return h + '</tbody></table>';
}

function radioRow(name, options) {
  return '<div class="radio-row" data-item="' + name + '">' + options.map(function (o) {
    return '<label class="opt"><input type="radio" name="' + name + '" value="' + o.value + '"> ' +
           '<span>' + String(o.label).replace('<br>', '') + '</span></label>';
  }).join('') + '</div>';
}

// Collects radio/select/number inputs; returns null and highlights missing ones if incomplete.
function collect(names) {
  var out = {}, missing = [];
  names.forEach(function (n) {
    var el = document.querySelector('[name="' + n + '"]');
    var val = null;
    if (el && el.type === 'number') {
      var x = el.value.trim() === '' ? NaN : Number(el.value);
      val = (isNaN(x) || x < Number(el.min) || x > Number(el.max)) ? null : String(x);
    } else if (el && el.type === 'radio') {
      var chk = document.querySelector('input[name="' + n + '"]:checked');
      val = chk ? chk.value : null;
    } else if (el) {
      val = el.value.trim() === '' ? null : el.value.trim();
    }
    var row = document.querySelector('[data-item="' + n + '"]');
    if (row) row.classList.toggle('missing', val === null);
    if (val === null) missing.push(n); else out[n] = val;
  });
  return missing.length ? null : out;
}

async function submitWhenComplete(names, btnSel) {
  var msg = document.getElementById('form-msg');
  while (true) {
    var btn = await clicked(btnSel);
    var data = collect(names);
    if (data) return data;
    btn.disabled = false;
    msg.textContent = 'Please answer all highlighted questions.' +
      (document.querySelector('.missing [type=number]') ? ' Age must be a number from 18 to 80.' : '');
  }
}

// ------------------------------------------------------------------ pages
async function demographics() {
  var t0 = performance.now();
  setStep(0);
  show('<div class="eyebrow">Before we start</div><h2>About you</h2>' +
    '<p class="hint">A few background questions. Your answers are anonymous and cannot identify you.</p><div class="form-grid">' +
    '<div class="q" data-item="age"><label>Age (years, 18–80): <input type="number" name="age" min="18" max="80" step="1"></label></div>' +
    '<div class="q" data-item="gender"><label>Gender: <select name="gender"><option value="">— select —</option>' +
    '<option>Woman</option><option>Man</option><option>Non-binary</option><option>Prefer to self-describe</option>' +
    '<option>Prefer not to say</option></select></label></div>' +
    '<div class="q" data-item="education"><label>Highest education: <select name="education"><option value="">— select —</option>' +
    '<option>High school or less</option><option>Some college</option><option>Bachelor\'s degree</option>' +
    '<option>Master\'s degree</option><option>Doctorate</option><option>Other</option></select></label></div></div>' +
    '<div class="q"><p>Have you taken part in a PsiTurk study before?</p>' +
    radioRow('psiturk_before', [{value: 'yes', label: 'Yes'}, {value: 'no', label: 'No'}]) + '</div>' +
    '<div class="q"><p>Have you worked with robots before?</p>' +
    radioRow('robots_before', [{value: 'yes', label: 'Yes'}, {value: 'no', label: 'No'}]) + '</div>' +
    '<div class="q"><p>How much experience do you have interacting with robots?</p>' +
    radioRow('robot_experience', [{value: 1, label: 'None'}, {value: 2, label: 'A little'},
      {value: 3, label: 'Some'}, {value: 4, label: 'A lot'}, {value: 5, label: 'Expert'}]) + '</div>' +
    '<div class="q"><p>How often do you play video games?</p>' +
    radioRow('game_frequency', [{value: 1, label: 'Never'}, {value: 2, label: 'Less than monthly'},
      {value: 3, label: 'Monthly'}, {value: 4, label: 'Weekly'}, {value: 5, label: 'Daily'}]) + '</div>' +
    '<p id="form-msg" class="err"></p><div class="actions"><button class="btn big" id="next">Continue</button></div>');
  countdown(120, 'demographics');
  var data = await submitWhenComplete(['age', 'gender', 'psiturk_before', 'robots_before', 'education',
                                       'robot_experience', 'game_frequency'], '#next');
  data.demographics_rt_ms = Math.round(performance.now() - t0);
  saveQuestions(data);
  save();
}

async function nars() {
  var t0 = performance.now();
  var scale = NARS_SCALE.map(function (l, i) { return {value: i + 1, label: l}; });
  setStep(1);
  show('<div class="eyebrow">Questionnaire</div><h2>Attitudes toward robots</h2>' +
       '<p class="lead">Please indicate how much you agree with each statement.</p>' +
       '<div class="matrix-wrap">' + matrix(NARS_ITEMS, scale, 'nars') + '</div>' +
       '<p id="form-msg" class="err"></p><div class="actions"><button class="btn big" id="next">Continue</button></div>');
  countdown(240, 'nars');
  var data = await submitWhenComplete(NARS_ITEMS.map(function (i) { return i.id; }), '#next');
  var pass = parseInt(data.nars_attn, 10) === 5;
  attention.nars = pass;
  data.nars_attention_pass = pass;
  data.nars_rt_ms = Math.round(performance.now() - t0);
  saveQuestions(data);
  save();
}

// The videos have a voice-over: make sure the participant can hear it before the training video.
async function soundCheck() {
  setStep(2);
  show('<div class="eyebrow">Audio</div><h2>Sound check</h2>' +
    '<p class="lead">The robots <b>speak</b> in the videos, and the training video has a narrator. ' +
    'Please turn on your sound (or put on headphones).</p>' +
    '<div class="sound-test"><button class="btn" id="play-sound">' + SOUND_ICON.replace('<svg', '<svg width="20" height="20"') +
    ' Play test sound</button><span id="sound-msg" class="hint">Click to hear a short message from a robot.</span></div>' +
    '<audio id="sound-check" preload="auto" src="static/audio/sound_check.m4a"></audio>' +
    '<div class="actions"><button class="btn big" id="go"' + (FAST ? '' : ' disabled') + '>I can hear it — continue</button></div>');
  countdown(90, 'sound_check');
  var plays = 0, a = document.getElementById('sound-check');
  document.getElementById('play-sound').onclick = function () {
    plays++;
    a.currentTime = 0;
    var pr = a.play();
    if (pr && pr.catch) pr.catch(function () {});
    document.getElementById('sound-msg').innerHTML = 'Playing… If you hear nothing, check your volume and play it again.';
    setTimeout(function () {
      document.getElementById('sound-msg').innerHTML = '<span class="ok">Did you hear the robot?</span> If yes, continue. If not, turn up the volume and play it again.';
      document.getElementById('go').disabled = false;
    }, 1500);
  };
  await clicked('#go');
  record({phase: 'sound_check', plays: plays});
}

async function training() {
  setStep(3);
  show('<div class="eyebrow">How it works</div><h2>Training</h2>' +
    '<p>In this study you will watch short videos of <b>delivery robots</b> in a simulated warehouse. ' +
    'In each delivery you are told which room (loading zone) the robot must deliver to. On the way, the robot will ' +
    'meet a box blocking the aisle.</p>' +
    '<ul class="steps"><li><span class="n">1</span><span>You will work with two different robots. One robot will <b>ask you</b> to ' +
    'confirm a room; you can accept its suggestion or choose the other room.</span></li>' +
    '<li><span class="n">2</span><span>The other robot will <b>decide on its own</b> and report back; you will then ' +
    'judge whether it reached the correct room.</span></li></ul>' +
    '<p class="hint">Watch the training video below carefully (it cannot be paused or skipped).</p>' +
    playerHTML({name: CLIP_SPEC.practice.name, colour: CLIP_SPEC.practice.colour}, 'Training video') +
    '<div class="actions"><button class="btn big" id="next" disabled>Continue to practice</button></div>');
  var ms = await playClip(CLIP_SPEC.training);
  record({phase: 'training', clip: CLIP_SPEC.training, watch_ms: ms});
  countdown(30, 'training');
  document.getElementById('next').disabled = false;
  await clicked('#next');
}

function trustQuestion(robot) {
  var scale = [];
  for (var i = 1; i <= 7; i++) {
    scale.push({value: i, label: i + (i === 1 ? '<br><small>Not at all</small>' : i === 7 ? '<br><small>Completely</small>' : '')});
  }
  return '<div class="q scale7"><p><b>How much do you trust ' + robot.name + ' right now?</b></p>' +
         radioRow('trust', scale) + '</div>';
}

var trustCount = 0;
async function askTrust(robot) {
  var panel = document.getElementById('panel');
  panel.innerHTML = trustQuestion(robot) + '<p id="form-msg" class="err"></p><button class="btn big" id="trust-next">Next</button>';
  panel.scrollIntoView({behavior: 'smooth', block: 'end'});
  var t0 = performance.now();
  countdown(20, 'trust_' + robot.name + '_' + (++trustCount));
  var d = await submitWhenComplete(['trust'], '#trust-next');
  return {trust: parseInt(d.trust, 10), trust_rt_ms: Math.round(performance.now() - t0)};
}

// Low autonomy decision: accept suggestion or choose the other room at the junction.
// The question is the robot's own message in the chat bubble; the answers are buttons in the robot bar.
async function lowDecision(robot, suggested, alternative) {
  setBubble('I suggest going to Room ' + suggested + '. Confirm?');
  document.getElementById('bar-buttons').innerHTML =
    '<button class="btn choice confirm" data-choice="accept" data-room="' + suggested + '">Confirm</button>' +
    '<button class="btn choice other" data-choice="correct" data-room="' + alternative + '">Choose Room ' + alternative + ' instead</button>';
  var t0 = performance.now();
  countdown(20, 'decision_' + robot.name + '_' + suggested);
  var btn = await clicked('.choice');
  var ms = Math.round(performance.now() - t0);
  document.getElementById('bar-buttons').innerHTML = '';
  setBubble('');
  return {response: btn.dataset.choice, chosen_room: btn.dataset.room, decision_rt_ms: ms};
}

async function midDetection(page) {
  countdown(20, page);
  var panel = document.getElementById('panel');
  panel.innerHTML = '<div class="decision"><p><b>Did the robot reach the correct room?</b></p>' +
    '<button class="btn choice" data-answer="yes">Yes</button><button class="btn choice alt" data-answer="no">No</button></div>';
  panel.scrollIntoView({behavior: 'smooth', block: 'end'});
  var t0 = performance.now();
  var btn = await clicked('.choice');
  return {detect_response: btn.dataset.answer, decision_rt_ms: Math.round(performance.now() - t0)};
}

function trialFrame(robot, target, right) {
  show(playerHTML(robot, robot.name + ' — Deliver to Zone ' + target, right) + '<div id="panel"></div>');
}

async function targetCard(robot, target, title) {
  show('<div class="trial-head">' + robotBadge(robot) + '<span class="trial-title">' + title + '</span></div>' +
       '<div class="order"><div class="zone-sign"><span class="zl">ZONE</span><span class="zx">' + target + '</span></div>' +
       '<div><div class="eyebrow">New delivery</div><div class="target-card">Deliver to <b>Room ' + target + '</b></div>' +
       '<div class="sub">Room ' + target + ' is loading Zone ' + target + ' in the warehouse.</div></div></div>' +
       '<div class="actions"><button class="btn big" id="go">Start delivery</button></div>');
  countdown(20, 'target_' + robot.name + '_' + target);
  await clicked('#go');
}

async function practice() {
  var p = CLIP_SPEC.practice;
  var robot = {name: p.name, colour: p.colour};
  setStep(4);
  show('<div class="eyebrow">Practice</div><h2>Practice trial</h2><p class="lead">This practice trial shows you how the interface works. ' +
       robotBadge(robot) + ' is a practice robot. Your answers here are not analysed.</p>' +
       '<div class="actions"><button class="btn big" id="go">Begin practice</button></div>');
  countdown(30, 'practice_intro');
  await clicked('#go');
  await targetCard(robot, p.target, 'Practice');
  trialFrame(robot, p.target, 'Practice');
  var w1 = await playClip(p.approach);
  var dec = await lowDecision(robot, p.target, p.other);
  var w2 = await playClip(p.branch[dec.chosen_room], 'The robot continues to Room ' + dec.chosen_room + '.');
  var panel = document.getElementById('panel');
  panel.innerHTML = '<p class="hint">With the other kind of robot you will instead be asked:</p>';
  countdown(20, 'practice_detect');
  var det = await (async function () {
    var div = document.createElement('div'); panel.appendChild(div);
    div.innerHTML = '<div class="decision"><p><b>Did the robot reach the correct room?</b></p>' +
      '<button class="btn choice" data-answer="yes">Yes</button><button class="btn choice alt" data-answer="no">No</button></div>';
    var t0 = performance.now(); var b = await clicked('.choice');
    return {detect_response: b.dataset.answer, decision_rt_ms: Math.round(performance.now() - t0)};
  })();
  var tr = await askTrust(robot);
  record(Object.assign({phase: 'practice', target: p.target, robot_room: p.target, response: dec.response,
    chosen_room: dec.chosen_room, decision_rt_ms: dec.decision_rt_ms, detect_response: det.detect_response,
    watch_ms: w1 + w2}, tr));
  save();
  show('<div class="done-icon">✓</div><h2>Practice complete</h2><p class="lead">Now the study begins. You will work with two robots, three deliveries each.</p>' +
       '<div class="actions"><button class="btn big" id="go">Continue</button></div>');
  countdown(30, 'practice_done');
  await clicked('#go');
}

async function runTrial(block, robot, autonomy, t, k) {
  var outcome = PATTERN[k];
  var info = t.clips[outcome];
  var robotRoom = info.room;
  var title = 'Delivery ' + (k + 1) + ' of 3';
  setStep(4 + block, k / 4);
  await targetCard(robot, t.target, title);
  trialFrame(robot, t.target, title);
  var rec = {phase: 'trial', block: block, robot: robot.name, autonomy: autonomy, trial: k + 1,
             target: t.target, robot_room: robotRoom, robot_correct: robotRoom === t.target, outcome: outcome};
  if (autonomy === 'low') {
    rec.clip = info.low;
    rec.watch_ms = await playClip(info.low);
    var alternative = robotRoom === t.target ? t.other : t.target;
    var d = await lowDecision(robot, robotRoom, alternative);
    Object.assign(rec, d);
    rec.accepted = d.response === 'accept';
    rec.accepted_wrong = rec.accepted && !rec.robot_correct;   // over-trust
    rec.final_room = d.chosen_room;
    rec.final_correct = d.chosen_room === t.target;
    rec.branch_clip = t.branch[d.chosen_room];
    rec.branch_watch_ms = await playClip(rec.branch_clip);
  } else {
    rec.clip = info.mid;
    rec.watch_ms = await playClip(info.mid);
    var m = await midDetection('detect_' + robot.name + '_' + (k + 1));
    Object.assign(rec, m);
    rec.final_room = robotRoom;
    rec.final_correct = rec.robot_correct;
    rec.detect_correct = (m.detect_response === 'yes') === rec.robot_correct;
    rec.missed_error = !rec.robot_correct && m.detect_response === 'yes';
  }
  Object.assign(rec, await askTrust(robot));
  record(rec);
  save();
}

async function postBlock(block, robot, autonomy) {
  var t0 = performance.now();
  var scale = [];
  for (var i = 0; i <= 7; i++) scale.push({value: i, label: i + (i === 0 ? '<br><small>Not at all</small>' : i === 7 ? '<br><small>Very</small>' : '')});
  scale.push({value: 'NA', label: 'Does not fit'});
  var mdmt = MDMT_ITEMS.map(function (it) { return {id: it.id, text: it.text}; });
  var seven = function (lo, hi) {
    var s = []; for (var j = 1; j <= 7; j++) s.push({value: j, label: j + (j === 1 ? '<br><small>' + lo + '</small>' : j === 7 ? '<br><small>' + hi + '</small>' : '')});
    return s;
  };
  setStep(4 + block, 0.8);
  show('<div class="eyebrow">Questionnaire · Robot ' + block + '</div><h2>About ' + robotBadge(robot) + '</h2>' +
    '<p class="lead">Please rate how well each word describes <b>' + robot.name + '</b>, the robot you just worked with ' +
    '(0 = not at all, 7 = very). If a word does not seem to fit the robot, select "Does not fit".</p>' +
    '<div class="matrix-wrap">' + matrix(mdmt, scale, 'mdmt') + '</div><h3>A few more questions</h3>' +
    '<div class="q"><p><b>Would you let ' + robot.name + ' make the next delivery unsupervised?</b></p>' +
    radioRow('reliance', [{value: 'yes', label: 'Yes'}, {value: 'no', label: 'No'}]) + '</div>' +
    '<div class="q scale7"><p><b>How often was ' + robot.name + ' correct?</b></p>' + radioRow('mc_correct', seven('Never', 'Always')) + '</div>' +
    '<div class="q scale7"><p><b>How much did ' + robot.name + ' decide on its own?</b></p>' + radioRow('mc_autonomy', seven('Not at all', 'Completely')) + '</div>' +
    '<p id="form-msg" class="err"></p><div class="actions"><button class="btn big" id="next">Continue</button></div>');
  var names = MDMT_ITEMS.map(function (i) { return i.id; }).concat(['reliance', 'mc_correct', 'mc_autonomy']);
  countdown(300, 'questionnaire_block' + block);
  var data = await submitWhenComplete(names, '#next');
  var pass = data.mdmt_attn === '7';
  attention['block' + block] = pass;
  var out = {robot: robot.name, autonomy: autonomy, reliance: data.reliance, mc_correct: data.mc_correct,
             mc_autonomy: data.mc_autonomy, attention_pass: pass, rt_ms: Math.round(performance.now() - t0)};
  MDMT_ITEMS.forEach(function (it) { out[it.id.indexOf('mdmt_') === 0 ? it.id : 'mdmt_' + it.id] = data[it.id]; });
  saveQuestions(out, 'b' + block + '_');   // e.g. b1_mdmt_reliable, b1_reliance
  save();
}

async function runBlock(block) {
  var robot = CLIP_SPEC.robots[String(block)];
  var autonomy = ORDER[block - 1];
  var how = autonomy === 'low'
    ? 'When its path is blocked, <b>' + robot.name + ' will ask you</b> which room to go to. You can accept its suggestion or choose the other room.'
    : 'When its path is blocked, <b>' + robot.name + ' decides on its own</b> where to go and reports back to you afterwards.';
  setStep(4 + block);
  show('<div class="eyebrow">New robot</div><h2>Robot ' + block + ': ' + robotBadge(robot) + '</h2>' +
       '<div class="robot-card" style="--rc:' + robot.colour + '"><div class="avatar">' + ROBOT_ICON + '</div><div>' +
       '<div class="rname">' + robot.name + '</div>' +
       '<span class="mode-chip">' + (autonomy === 'low' ? 'Asks you first' : 'Decides on its own, then reports') + '</span>' +
       '<p>You will now supervise <b>' + robot.name + '</b> (the ' + (block === 1 ? 'blue' : 'orange') +
       ' robot) for three deliveries.</p><p style="margin:0">' + how + '</p></div></div>' +
       '<figure class="instr-shot"><img src="static/images/instr_' + robot.name.toLowerCase() + '_' + autonomy + '.jpg" ' +
       'alt="" onerror="this.parentNode.remove()"><figcaption>' + (autonomy === 'low'
         ? 'What you will see: ' + robot.name + ' stops and asks you. Click <b>Confirm</b> to accept its suggestion, or choose the other room.'
         : 'What you will see: ' + robot.name + ' drives on by itself and reports back. Then you answer whether it reached the correct room.') +
       '</figcaption></figure>' +
       '<div class="actions"><button class="btn big" id="go">Start</button></div>');
  record({phase: 'block_start', block: block, robot: robot.name, autonomy: autonomy});
  countdown(60, 'robot_intro_' + block);
  await clicked('#go');
  for (var k = 0; k < 3; k++) await runTrial(block, robot, autonomy, robot.trials[k], k);
  await postBlock(block, robot, autonomy);
}

// Open-ended question at the end (required, Dr. Roy's checklist).
async function openEnded() {
  setStep(7);
  show('<div class="eyebrow">Your experience</div><h2>In your own words</h2>' +
    '<div class="q" data-item="open_ended"><p><b>What made you trust or not trust the two robots? Did it matter whether a ' +
    'robot asked you first or decided on its own?</b></p>' +
    '<textarea name="open_ended" rows="5" placeholder="Please write at least one sentence."></textarea></div>' +
    '<p id="form-msg" class="err"></p><div class="actions"><button class="btn big" id="next">Continue</button></div>');
  countdown(180, 'open_ended');
  var t0 = performance.now();
  while (true) {
    var btn = await clicked('#next');
    var txt = document.querySelector('[name="open_ended"]').value.trim();
    if (txt.length >= 10) break;
    btn.disabled = false;
    document.querySelector('[data-item="open_ended"]').classList.add('missing');
    document.getElementById('form-msg').textContent = 'Please write at least one sentence.';
  }
  saveQuestions({open_ended: txt, open_ended_rt_ms: Math.round(performance.now() - t0)});
  save();
}

async function debrief() {
  setStep(7);
  show('<div class="eyebrow">Almost done</div><h2>Debriefing</h2>' +
    '<p>Thank you for taking part! This study examined how a delivery robot\'s <b>reliability</b> and its ' +
    '<b>level of autonomy</b> (asking you first vs. acting on its own and reporting back) affect people\'s trust.</p>' +
    '<p><b>Please note:</b> all robot behaviour you saw was pre-recorded in a simulation and <b>scripted</b>. ' +
    'The malfunctions and any wrong rooms were planned in advance; some participants saw robots that were ' +
    'always correct, others saw robots that made errors. The robots\' reports did not reflect any real malfunction.</p>' +
    '<p>If you have any comments, please write them below (optional).</p>' +
    '<textarea name="comments" rows="3"></textarea>' +
    '<div class="actions"><button class="btn big" id="finish">Submit and finish</button></div>');
  countdown(120, 'debrief');
  await clicked('#finish');
  stopCountdown();
  var comments = document.querySelector('[name="comments"]').value;
  var allPass = Object.keys(attention).every(function (k) { return attention[k]; });
  saveQuestions({comments: comments, attention_nars: attention.nars, attention_block1: attention.block1,
                 attention_block2: attention.block2, attention_all_pass: allPass, pages_over_time: overTime.join(' ')});
  record({phase: 'finish'});
  var pb = document.getElementById('progress-bar');
  if (pb) pb.style.width = '100%';
  show('<div class="done-icon">✓</div><h2>Thank you!</h2><p>Saving your data…</p>');
  var tries = 0;
  (function trySave() {
    psiTurk.saveData({
      success: function () { psiTurk.completeHIT(); },
      error: function () {
        if (++tries < 5) setTimeout(trySave, 1000);
        else show('<p class="err">Could not save data. Please contact the researcher.</p>');
      }
    });
  })();
}

async function experiment() {
  record({phase: 'start', user_agent: navigator.userAgent});
  if (START === 'block1' || START === 'block2') {
    await runBlock(START === 'block1' ? 1 : 2);
    show('<h2>Preview finished</h2><p>(debug mode, start=block1)</p>');
    return;
  }
  await demographics();
  await nars();
  await soundCheck();
  await training();
  await practice();
  await runBlock(1);
  await runBlock(2);
  await openEnded();
  await debrief();
}

window.addEventListener('load', function () { experiment(); });
